    display: flex;
    width: max-content;
    animation: ticker-scroll 28s linear infinite;
  }
  .ticker-track:hover { animation-play-state: paused; }

  /* ── Fade-in on scroll ── */
  @keyframes fadeInUp {
    from { opacity: 0; transform: translateY(24px); }
    to { opacity: 1; transform: translateY(0); }
