    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    z-index: 100;
  }
  .nav-item.active .mega-menu,
  .nav-item:hover .mega-menu {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
