<script>
  // Initialize Lucide icons
  lucide.createIcons();

  // ── Mobile Menu Toggle ──
  const mobileToggle = document.getElementById('mobileMenuToggle');
  const mobileNav = document.getElementById('mobileNav');
  mobileToggle.addEventListener('click', () => {
    const isOpen = mobileNav.classList.toggle('open');
    mobileToggle.setAttribute('aria-expanded', isOpen);
    mobileToggle.querySelector('[data-lucide]').setAttribute('data-lucide', isOpen ? 'x' : 'menu');
    lucide.createIcons();
  });

  // ── Desktop Mega Menu Toggle (click for touch/mobile-first behavior) ──
  document.querySelectorAll('.nav-item').forEach(item => {
    const btn = item.querySelector('button');
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const wasActive = item.classList.contains('active');
      // Close all
      document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
      // Toggle clicked
      if (!wasActive) item.classList.add('active');
    });
  });

  // Close mega menus when clicking outside
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.nav-item')) {
      document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
    }
  });

  // ── Recommended Reads Tabs ──
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabPanels = document.querySelectorAll('.tab-content');

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const tabId = btn.dataset.tab;

      // Update buttons
      tabBtns.forEach(b => {
        b.setAttribute('aria-selected', 'false');
        b.classList.remove('active');
        b.style.background = '';
        b.style.color = '';
      });
      btn.setAttribute('aria-selected', 'true');
      btn.classList.add('active');
      btn.style.background = 'var(--teal)';
      btn.style.color = 'white';

      // Update panels with fade
      tabPanels.forEach(panel => {
        if (panel.dataset.tab === tabId) {
          panel.classList.remove('hidden-tab');
          panel.style.opacity = '0';
          panel.style.transform = 'translateY(8px)';
          requestAnimationFrame(() => {
            panel.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
            panel.style.opacity = '1';
            panel.style.transform = 'translateY(0)';
          });
        } else {
          panel.classList.add('hidden-tab');
        }
      });
    });
  });

  // ── Health Topics Carousel ──
  const carousel = document.getElementById('topicsCarousel');
  const prevBtn = document.getElementById('topicsPrev');
  const nextBtn = document.getElementById('topicsNext');

  if (carousel && prevBtn && nextBtn) {
    const scrollAmount = 320;
    prevBtn.addEventListener('click', () => carousel.scrollBy({ left: -scrollAmount, behavior: 'smooth' }));
    nextBtn.addEventListener('click', () => carousel.scrollBy({ left: scrollAmount, behavior: 'smooth' }));
  }

  // ── Newsletter Form (hero section) ──
  document.getElementById('newsletterForm').addEventListener('submit', function(e) {
    e.preventDefault();
    const input = this.querySelector('input[type="email"]');
    if (input.value.trim()) {
      // Simulate subscription
      const btn = this.querySelector('button');
      const originalHTML = btn.innerHTML;
      btn.innerHTML = '<i data-lucide="check" class="w-4 h-4 inline mr-1"></i> Subscribed!';
      btn.style.background = '#16a34a';
      btn.disabled = true;
      input.value = '';
      setTimeout(() => {
        btn.innerHTML = originalHTML;
        btn.style.background = '';
        btn.disabled = false;
        lucide.createIcons();
      }, 3000);
    }
  });

  // ── Footer Newsletter Form ──
  document.getElementById('footerNewsletterForm').addEventListener('submit', function(e) {
    e.preventDefault();
    const input = this.querySelector('input[type="email"]');
    if (input.value.trim()) {
      const btn = this.querySelector('button');
      const originalHTML = btn.innerHTML;
      btn.innerHTML = '<i data-lucide="check" class="w-4 h-4 inline mr-1"></i> Signed Up!';
      btn.style.background = '#16a34a';
      btn.disabled = true;
      input.value = '';
      setTimeout(() => {
        btn.innerHTML = originalHTML;
        btn.style.background = '';
        btn.disabled = false;
        lucide.createIcons();
      }, 3000);
    }
  });

  // ── Intersection Observer for scroll animations ──
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.style.opacity = '1';
      }
    });
  }, { threshold: 0.15 });

  document.querySelectorAll('.animate-in').forEach(el => observer.observe(el));

  // ── Smooth scroll for all anchor links ──
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
      const target = document.querySelector(this.getAttribute('href'));
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth' });
      }
    });
  });
</script>
